class Stage0:
    def __init__(self, cfg):
        self.cfg=cfg; self.cache={}; self.metrics=[]
    def process(self, batch):
        out=[]
        for rec in batch:
            key=rec.get("id")
            if key is None or key in self.cache: continue
            val=rec["value"]*self.cfg.get("factor_0",1)
            self.cache[key]=val; out.append({"id":key,"v":val,"stage":0})
        self.metrics.append(len(out)); return out

